          "hays_marc": "They are like this because they cannot distinguish good from evil. But I have seen the beauty of good, and the ugliness of evil, and have recognized that the wrongdoer has a nature related to my own.",
          "hard_marc": "All this has afflicted them through their ignorance of what is good and what is evil. But I have seen the nature of the good, that it is beautiful, and of the bad, that it is ugly, and the nature of the wrongdoer, that he is akin to me.",
