          "strassler_hero": "so that human achievements may not become forgotten in time, and great and marvelous deeds—some displayed by Greeks, some by barbarians—may not be without their glory; and especially to show why the two peoples fought with each other.",
          "evans_hero": "so that what men have done may not be erased by time, nor the great and astonishing deeds of Greeks and non-Greeks fail of their renown; and in particular why they went to war.",
          "waterfield_hero": "so that what human beings have done does not fade in time, and great and remarkable deeds—some performed by Greeks, some by barbarians—do not lose their glory; and especially to show what caused them to go to war with one another.",
          "mensch_hero": "so that human deeds may not be erased by time, and great and wondrous works—some produced by Greeks, some by barbarians—may not lack renown; and in particular why they went to war with each other.",
          "holland_hero": "so that what has happened to mankind will not fade with time, and the great and wondrous feats—some displayed by Greeks, some by barbarians—may not lose their renown; and also the reason why they went to war with one another.",
