    "format": "Verse (Sapphic Strophe)",
    "genre": "Lyric Poetry",
    "description": "Sappho's Fragment 31 — 'He seems to me equal to the gods' — is one of the most celebrated poems in all of antiquity, a perfect specimen of erotic lyric in the Sapphic strophe. The poem describes the physical symptoms of overwhelming desire as the speaker watches a man converse with a woman she loves. It became a touchstone text for discussions of passionate love, and Longinus cited it as the supreme example of the sublime.",
