          "ref": "17c",
          "cary_apo2": "Most of all was I astonished at one of the many falsehoods which they told: when they said that you should beware of being deceived by me, as being powerful in speaking.",
          "lamb_apo2": "But of the many falsehoods they told, one in particular surprised me, when they said you must be careful not to be deceived by me, because I am a clever speaker.",
          "cooper_apo2": "Most of all was I amazed at one of the many lies they told: when they warned you to be on your guard against being deceived by me, because I was an accomplished speaker.",
          "reeve_apo2": "Among the many falsehoods they told, there was one in particular that amazed me, when they said you ought to beware of being deceived by me, because I am a clever speaker.",
